import io,json,urllib.request,zipfile,re
def handler(event,ctx):
    url=event.get('url')
    needles=event.get('needles') or ['ivr-default','customerservice','POST_CALL_SMS','content']
    with urllib.request.urlopen(url,timeout=20) as r:
        data=r.read()
    z=zipfile.ZipFile(io.BytesIO(data))
    out=[]
    for name in z.namelist():
        if not name.endswith('.py'): continue
        try: txt=z.read(name).decode('utf-8','replace')
        except Exception: continue
        lines=txt.splitlines()
        for i,line in enumerate(lines):
            if any(n.lower() in line.lower() for n in needles):
                a=max(0,i-5); b=min(len(lines),i+8)
                out.append({'file':name,'line':i+1,'snippet':'\n'.join(lines[a:b])})
    return {'matches':out[:40]}
